import {createDemo,demoAction,demoCell,demoProgress,regionKey,loadRegionQueue,saveRegionQueue,regionViewUrl,DEMO_STAGES} from './ai-demo-model.js';
import {regionMapMarkup,mountRegionMap} from './ai-region-map.js';
export function aiConnectorMarkup(){return `<main id="main" class="ai-page" data-ai-demo>
<div class="ai-heading"><h1>Choose where your AI looks.</h1></div>
<p class="ai-intro">Select regions on the sky map. Your assistant works through them in order.</p>
<div class="ai-workbench">
<div class="ai-controls">
<label for="ai-assistant">Assistant</label><select id="ai-assistant"><option>ChatGPT</option><option>Claude</option><option>Gemini</option></select>
<div class="ai-connection"><span id="ai-connection-state">Not connected</span><button id="ai-connect" type="button">Connect demo</button></div>
<div class="ai-queue-heading"><span id="ai-queue-count">0 regions selected</span><button id="ai-clear" type="button" disabled>Clear</button></div>
<ol id="ai-queue" class="ai-queue" aria-label="Selected regions in processing order"></ol><p id="ai-empty" class="ai-empty">Select regions on the map to build your queue.</p>
<div class="ai-actions"><button id="ai-run" class="button" type="button" disabled>Run selected regions <span aria-hidden="true">→</span></button><button id="ai-pause" class="button outline" type="button" hidden>Pause</button><button id="ai-reset" type="button" hidden>Edit queue</button></div>
<p class="ai-disclosure">Real sky regions. AI execution is a preview; no account or allowance is used.</p>
</div>
<div class="ai-workspace">
<div class="ai-run-heading"><p id="ai-status" role="status" aria-live="polite">Choose your first region.</p><span id="ai-count">0 / 0</span></div>
${regionMapMarkup()}
<div class="ai-progress-row"><progress id="ai-progress" max="100" value="0" aria-label="Selected region progress"></progress><span id="ai-percent">0%</span></div>
<div class="ai-detail"><div class="ai-detail-copy"><div><strong id="ai-cell-title">No region selected</strong><span id="ai-cell-state"></span></div><p id="ai-cell-note">Your selected regions appear here in order.</p><div class="ai-steps" aria-hidden="true">${DEMO_STAGES.map((s,i)=>`<span data-ai-step="${i}" title="${s}"></span>`).join('')}</div></div><a id="ai-open-region" class="ai-open-region" hidden>Open observations <span aria-hidden="true">↗</span></a></div>
</div></div></main>`;}
export function mountAiConnector(root=document.querySelector('[data-ai-demo]')){
 if(!root)return()=>{};let storage;try{storage=window.localStorage;}catch{}let state=createDemo(loadRegionQueue(storage)),timer=null,closed=false,map=null,lastSelection='',lastActive='';const q=s=>root.querySelector(s);
 function dispatch(action,value){if(closed)return;state=demoAction(state,action,value);if(action==='regions')saveRegionQueue(storage,state.regions);paint();if(state.status!=='running'){clearTimeout(timer);timer=null;}else if(timer===null)timer=setTimeout(()=>{timer=null;dispatch('tick');},1300);}
 function paint(){
  const connected=state.status!=='disconnected',busy=['running','paused','complete'].includes(state.status),running=state.status==='running',current=state.regions[state.completed],selected=state.regions.find(r=>regionKey(r)===state.selected)||current;
  q('#ai-assistant').value=state.assistant;q('#ai-assistant').disabled=connected;q('#ai-connect').textContent=connected?'Disconnect':'Connect demo';q('#ai-connection-state').textContent=connected?state.assistant+' · preview':'Not connected';q('.ai-connection').classList.toggle('connected',connected);
  q('#ai-run').hidden=running||state.status==='complete';q('#ai-run').disabled=!connected||!state.regions.length;q('#ai-run').textContent=state.status==='paused'?'Resume queue →':'Run selected regions →';q('#ai-pause').hidden=!running;q('#ai-reset').hidden=!busy;q('#ai-clear').disabled=busy||!state.regions.length;
  const status=running?`Region ${state.completed+1} of ${state.regions.length} · ${current.label}`:state.status==='paused'?'Queue paused':state.status==='complete'?'Preview complete · no AI results generated':state.regions.length?connected?'Ready to run your selected regions.':'Connect an assistant to run this queue.':'Choose your first region.';
  if(q('#ai-status').textContent!==status)q('#ai-status').textContent=status;q('#ai-count').textContent=`${state.completed} / ${state.regions.length}`;q('#ai-progress').value=demoProgress(state);q('#ai-percent').textContent=demoProgress(state)+'%';q('#ai-queue-count').textContent=state.regions.length+' region'+(state.regions.length===1?'':'s')+' selected';q('#ai-empty').hidden=!!state.regions.length;
  // Reconcile each region instead of replacing focused queue controls on ticks.
  const queue=q('#ai-queue'),keys=new Set(state.regions.map(regionKey));for(const row of [...queue.children])if(!keys.has(row.dataset.key))row.remove();
  state.regions.forEach((region,index)=>{const key=regionKey(region);let row=[...queue.children].find(row=>row.dataset.key===key);if(!row){row=document.createElement('li');row.dataset.key=key;row.innerHTML='<button type="button" class="ai-queue-select"><span class="ai-queue-number"></span><span><strong></strong></span><span class="ai-queue-state"></span></button><button type="button" class="ai-remove" aria-label="Remove region">×</button>';row.querySelector('.ai-queue-select').onclick=()=>{dispatch('select',key);map?.focus?.(region);};row.querySelector('.ai-remove').onclick=()=>dispatch('regions',state.regions.filter(r=>regionKey(r)!==key));queue.append(row);}if(queue.children[index]!==row)queue.insertBefore(row,queue.children[index]||null);const status=demoCell(state,key);row.dataset.state=status;row.querySelector('.ai-queue-number').textContent=String(index+1).padStart(2,'0');row.querySelector('strong').textContent=region.label;row.querySelector('.ai-queue-state').textContent=status==='reviewed'?'✓':status==='running'?'●':status==='paused'?'Ⅱ':'';row.querySelector('.ai-queue-select').setAttribute('aria-pressed',String(selected&&regionKey(selected)===key));row.querySelector('.ai-queue-select').setAttribute('aria-label',`${index+1}. ${region.label}, ${status==='reviewed'?'preview complete':status}`);row.querySelector('.ai-remove').disabled=busy;row.querySelector('.ai-remove').setAttribute('aria-label','Remove '+region.label);});
  const selectedStatus=selected?demoCell(state,regionKey(selected)):'unassigned';q('#ai-cell-title').textContent=selected?.label||'No region selected';q('#ai-cell-state').textContent=selectedStatus==='reviewed'?'Preview complete':selectedStatus==='running'?'Connector preview':selectedStatus==='paused'?'Paused':selectedStatus==='queued'?'Queued':'';q('#ai-cell-note').textContent=selectedStatus==='reviewed'?'Ready for real AI review when a connector is available.':selectedStatus==='running'?`Preview task: ${DEMO_STAGES[state.step].toLowerCase()}.`:selectedStatus==='paused'?'Resume to continue through your selected regions.':selected?`RA ${selected.ra.toFixed(4)}° · Dec ${selected.dec.toFixed(4)}°`:'Your selected regions appear here in order.';
  q('#ai-open-region').hidden=!selected;if(selected)q('#ai-open-region').href=regionViewUrl(selected);q('.ai-steps').hidden=!['running','paused','reviewed'].includes(selectedStatus);root.querySelectorAll('[data-ai-step]').forEach((el,i)=>{el.dataset.done=String(selectedStatus==='reviewed'||(['running','paused'].includes(selectedStatus)&&i<state.step));el.dataset.current=String(selectedStatus==='running'&&i===state.step);});
  const selection=JSON.stringify(state.regions);if(selection!==lastSelection){lastSelection=selection;map?.setSelection?.(state.regions);}const active=running||state.status==='paused'?current:null,key=active?regionKey(active):'';if(key!==lastActive){lastActive=key;map?.setActive?.(active||null);}map?.setDisabled?.(busy);
 }
 q('#ai-assistant').onchange=e=>dispatch('assistant',e.target.value);q('#ai-connect').onclick=()=>dispatch(state.status==='disconnected'?'connect':'disconnect');q('#ai-run').onclick=()=>{dispatch('start');if(state.status==='running')q('#ai-pause').focus();};q('#ai-pause').onclick=()=>{dispatch('pause');q('#ai-run').focus();};q('#ai-reset').onclick=()=>{dispatch('reset');q('#ai-run').focus();};q('#ai-clear').onclick=()=>dispatch('regions',[]);
 const visibility=()=>{if(document.hidden&&state.status==='running')dispatch('pause');};document.addEventListener('visibilitychange',visibility);paint();
 map=mountRegionMap(q('[data-ai-region-map]'),{onToggle:region=>{if(!['disconnected','ready'].includes(state.status))return;const key=regionKey(region),exists=state.regions.some(r=>regionKey(r)===key);dispatch('regions',exists?state.regions.filter(r=>regionKey(r)!==key):[...state.regions,region]);},onStatus:message=>{if(!closed&&message)q('#ai-status').textContent=message;}});lastSelection='';lastActive='';paint();
 return()=>{closed=true;clearTimeout(timer);map?.destroy?.();document.removeEventListener('visibilitychange',visibility);};
}
